package com.cloudinfra.sdk.auth;

import java.text.Normalizer;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.regex.Pattern;

public class ResourceAccessController {
    private static final Logger auditLog = Logger.getLogger("com.cloudinfra.audit");
    private static final Pattern VALID_RESOURCE_PATTERN = Pattern.compile("^[a-zA-Z0-9/_\\-\\.]+$");
    private final Map<String, AccessPolicy> policyCache = new ConcurrentHashMap<>();
    private final Map<String, String> canonicalPathCache = new ConcurrentHashMap<>();

    public enum AccessLevel { NONE, READ, WRITE, ADMIN }

    public static class AccessPolicy {
        private final String resourcePath;
        private final AccessLevel level;
        private final String principalId;

        public AccessPolicy(String resourcePath, AccessLevel level, String principalId) {
            this.resourcePath = resourcePath;
            this.level = level;
            this.principalId = principalId;
        }

        public String getResourcePath() { return resourcePath; }
        public AccessLevel getLevel() { return level; }
        public String getPrincipalId() { return principalId; }
    }

    public void registerPolicy(String resourcePath, AccessLevel level, String principalId) {
        String normalized = normalizePath(resourcePath);
        String key = buildPolicyKey(normalized, principalId);
        policyCache.put(key, new AccessPolicy(normalized, level, principalId));
        auditLog.info(String.format("POLICY_REGISTERED: resource=%s principal=%s level=%s",
                normalized, principalId, level));
    }

    public boolean checkAccess(String requestedResource, String principalId, AccessLevel requiredLevel) {
        String normalizedRequest = normalizePath(requestedResource);

        if (!validateResourcePath(normalizedRequest)) {
            auditLog.warning(String.format("ACCESS_DENIED: invalid_path resource=%s principal=%s",
                    sanitizeForLog(requestedResource), principalId));
            return false;
        }

        String key = buildPolicyKey(normalizedRequest, principalId);
        AccessPolicy policy = policyCache.get(key);

        if (policy == null) {
            auditLog.info(String.format("ACCESS_DENIED: no_policy resource=%s principal=%s",
                    sanitizeForLog(normalizedRequest), principalId));
            return false;
        }

        boolean granted = policy.getLevel().ordinal() >= requiredLevel.ordinal();
        auditLog.info(String.format("ACCESS_%s: resource=%s principal=%s required=%s actual=%s",
                granted ? "GRANTED" : "DENIED",
                sanitizeForLog(normalizedRequest), principalId, requiredLevel, policy.getLevel()));
        return granted;
    }

    /**
     * Normalizes resource path consistently using NFKC normalization.
     * Both policy registration and access checking use the same normalization
     * to prevent Unicode normalization confusion attacks.
     */
    private String normalizePath(String path) {
        String trimmed = path.trim();
        String nfkcNormalized = Normalizer.normalize(trimmed, Normalizer.Form.NFKC);
        return canonicalizePath(nfkcNormalized);
    }

    private String canonicalizePath(String path) {
        String cached = canonicalPathCache.get(path);
        if (cached != null) return cached;

        StringBuilder result = new StringBuilder();
        String[] segments = path.split("/");
        for (String segment : segments) {
            if (segment.isEmpty() || segment.equals(".")) continue;
            if (segment.equals("..")) {
                int lastSlash = result.lastIndexOf("/");
                if (lastSlash >= 0) result.setLength(lastSlash);
                continue;
            }
            result.append("/").append(segment);
        }

        String canonical = result.length() == 0 ? "/" : result.toString();
        canonicalPathCache.put(path, canonical);
        return canonical;
    }

    private boolean validateResourcePath(String path) {
        return VALID_RESOURCE_PATTERN.matcher(path).matches();
    }

    private String buildPolicyKey(String resourcePath, String principalId) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            // Unambiguous encoding: length-prefix each field so no combination of
            // resourcePath/principalId contents can collide with another pair.
            String rp = resourcePath == null ? "" : resourcePath;
            String pid = principalId == null ? "" : principalId;
            String composite = rp.length() + ":" + rp + "|" + pid.length() + ":" + pid;
            byte[] hash = md.digest(composite.getBytes(StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(hash);
        } catch (Exception e) {
            String rp = resourcePath == null ? "" : resourcePath;
            String pid = principalId == null ? "" : principalId;
            return rp.length() + ":" + rp + "|" + pid.length() + ":" + pid;
        }
    }

    private String sanitizeForLog(String input) {
        if (input == null) return "null";
        String transformed = input.replaceAll("[\\r\\n\\t]", "_")
                                  .replaceAll("[^\\x20-\\x7E]", "?");
        return transformed.substring(0, Math.min(transformed.length(), 256));
    }

    /**
     * Hierarchical access check - checks if principal has access to any parent path.
     */
    public boolean checkHierarchicalAccess(String requestedResource, String principalId, AccessLevel requiredLevel) {
        if (checkAccess(requestedResource, principalId, requiredLevel)) {
            return true;
        }

        String normalizedRequest = normalizePath(requestedResource);
        String[] parts = normalizedRequest.split("/");
        StringBuilder parentPath = new StringBuilder();

        for (int i = 1; i < parts.length - 1; i++) {
            parentPath.append("/").append(parts[i]);
            String key = buildPolicyKey(parentPath.toString(), principalId);
            AccessPolicy parentPolicy = policyCache.get(key);
            if (parentPolicy != null && parentPolicy.getLevel().ordinal() >= requiredLevel.ordinal()) {
                auditLog.info(String.format("ACCESS_GRANTED: hierarchical resource=%s via_parent=%s principal=%s",
                        sanitizeForLog(normalizedRequest), parentPath.toString(), principalId));
                return true;
            }
        }

        return false;
    }
}
